99	// NewHandler builds the public HTTP surface backed by s.
100	func NewHandler(s *store.Store) http.Handler {
101		mux := http.NewServeMux()
102	
103		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
104			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
105		})
106	
107		mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
108			handleRegisterDevice(s, w, r)
109		})
110		// Non-POST verbs on the exact collection path: the method-less pattern is
111		// less specific than POST above, so it only catches the rest and answers a
112		// JSON 404 instead of ServeMux's slash redirect.
113		mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
114			writeError(w, http.StatusNotFound, "unknown device path")
115		})
116		mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
117			writeError(w, http.StatusNotFound, "unknown session path")
118		})
119		mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
120			handleCreateSession(s, w, r)
121		})
122		mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
123			handleDeleteSession(s, w, r)
124		})
125		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, r *http.Request) {
126			handleCreateAttachment(s, w, r)
127		})
128		mux.HandleFunc("PUT /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
129			handlePutChunk(s, w, r)
130		})
131		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments/{attachmentId}/complete", func(w http.ResponseWriter, r *http.Request) {
132			handleCompleteAttachment(s, w, r)
133		})
134		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}", func(w http.ResponseWriter, r *http.Request) {
135			handleGetAttachment(s, w, r)
136		})
137		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
138			handleGetChunk(s, w, r)
139		})
140		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
141			handleSessionChanges(s, w, r)
142		})
143		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe", func(w http.ResponseWriter, r *http.Request) {
144			handleSubscribe(s, w, r)
145		})
146		// Non-GET verbs on the subscribe path get a JSON 400 rather than
147		// ServeMux's plain-text 405: the endpoint's only method is GET.
148		mux.HandleFunc("/v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe", func(w http.ResponseWriter, _ *http.Request) {
149			writeError(w, http.StatusBadRequest, "method is not allowed on this path")
150		})
151		// Any other path under the new namespaces is a JSON 404 rather than
152		// ServeMux's plain-text one: every failure of a new endpoint answers JSON.
153		// Exact method-patterns above take precedence over these subtree patterns.
154		mux.HandleFunc("/v1/devices/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
155			writeError(w, http.StatusNotFound, "unknown device/session path")
156		})
157		mux.HandleFunc("/v1/sessions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
158			writeError(w, http.StatusNotFound, "unknown session path")
159		})
160	
161		mux.HandleFunc("POST /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
162			handlePostChanges(s, w, r)
163		})
164		mux.HandleFunc("GET /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
165			handleListChanges(s, w, r)
166		})
167		mux.HandleFunc("GET /v1/documents/{documentID}/changes/poll", func(w http.ResponseWriter, r *http.Request) {
168			handlePollChanges(s, w, r)
169		})
170		// Non-GET verbs on the poll path: the exact GET pattern above is more
171		// specific, so only other verbs reach this method-less pattern and get a
172		// JSON 400 instead of ServeMux's plain-text 405.
173		mux.HandleFunc("/v1/documents/{documentID}/changes/poll", func(w http.ResponseWriter, _ *http.Request) {
174			writeError(w, http.StatusBadRequest, "method is not allowed on this path")
175		})
176		mux.HandleFunc("POST /v1/documents/{documentID}/replay", func(w http.ResponseWriter, r *http.Request) {
177			handleReplay(s, w, r)
178		})
179		mux.HandleFunc("/v1/documents/{documentID}/replay", func(w http.ResponseWriter, _ *http.Request) {
180			writeError(w, http.StatusBadRequest, "method is not allowed on this path")
181		})
182		mux.HandleFunc("POST /v1/documents/{documentID}/merge", func(w http.ResponseWriter, r *http.Request) {
183			handleMergeChange(s, w, r)
184		})
185		mux.HandleFunc("POST /v1/documents/{documentID}/snapshots", func(w http.ResponseWriter, r *http.Request) {
186			handlePostSnapshot(s, w, r)
187		})
188		mux.HandleFunc("GET /v1/documents/{documentID}/snapshots/{cursor}", func(w http.ResponseWriter, r *http.Request) {
189			handleGetSnapshot(s, w, r)
190		})
191		mux.HandleFunc("POST /v1/documents/{documentID}/restore", func(w http.ResponseWriter, r *http.Request) {
192			handleRestore(s, w, r)
193		})
194		mux.HandleFunc("POST /v1/documents/{documentID}/permissions", func(w http.ResponseWriter, r *http.Request) {
195			handleSetPermission(s, w, r)
196		})
197	
198		// ServeMux treats any empty path segment (the doubled slash in
199		// /v1/documents//..., /v1/devices//sessions or
200		// /v1/sessions//documents/...) as an unclean path and answers with a 307
201		// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
202		// error for an empty identifier, so intercept those paths before the mux
203		// sees them. A trailing slash empties the final id of the device/session
204		// routes and is rejected there for the same reason; the document routes
205		// keep their pre-existing ServeMux behavior.
206		return emptyIDGuard(mux)
207	}
208	
209	// emptyIDGuard rejects requests carrying an empty path identifier with a 400
210	// JSON error instead of letting ServeMux emit its HTML redirect or a
211	// plain-text 404.
212	//
213	// The document family keeps its original rule (an empty documentID, i.e. the
214	// prefix /v1/documents//); other odd paths there retain their old response so
215	// the pre-existing surface is unchanged. The new device/session families are
216	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
217	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
218	func emptyIDGuard(next http.Handler) http.Handler {
219		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
220			p := r.URL.Path
221	
222			documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
223			newFamilySegmentEmpty := false
224			if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
225				newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
226			}
227	
228			if documentSegmentEmpty || newFamilySegmentEmpty || malformedNewDocumentPath(p) || malformedSubscribePath(p) {
229				writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
230				return
231			}
232			next.ServeHTTP(w, r)
233		})
234	}
235	
236	// malformedNewDocumentPath reports whether p targets one of the new
237	// long-poll/replay endpoints but is not that endpoint's exact location: a
238	// missing/empty segment, a trailing slash, extra segments, or a "poll"/"replay"
239	// segment in a position short of the registered shape. ServeMux would answer
240	// those with a 301 redirect or a plain-text 404/405; the new endpoints promise
241	// a JSON error and never a redirect, so every such path is a malformed 400.
242	//
243	// Keywords are matched only past the documentID position, so documents that
244	// happen to be named "poll" or "replay" keep their ordinary merge/snapshot/
245	// changes routes.
246	func malformedNewDocumentPath(p string) bool {
247		rest, ok := strings.CutPrefix(p, "/v1/documents/")
248		if !ok {
249			return false
250		}
251		segs := strings.Split(rest, "/")
252	
253		// Poll endpoint: "poll" must be exactly the third segment, after a
254		// non-empty documentID and "changes".
255		for i, seg := range segs {
256			if seg == "poll" && i > 0 {
257				return !(len(segs) == 3 && segs[0] != "" && segs[1] == "changes")
258			}
259		}
260		// Replay endpoint: "replay" must be exactly the second segment, after a
261		// non-empty documentID.
262		for i, seg := range segs {
263			if seg == "replay" && i > 0 {
264				return !(len(segs) == 2 && segs[0] != "")
265			}
266		}
267		return false
268	}
269	
270	// malformedSubscribePath reports whether p targets the WebSocket subscription
271	// endpoint but is not at its exact location
272	// (/v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe): a
273	// missing "documents"/"changes" segment, an extra segment, or a "subscribe"
274	// segment short of the registered shape. ServeMux would answer those with a
275	// plain-text 404/405; every failure of this endpoint must be a JSON 400
276	// instead. Empty segments are already rejected by the guard itself.
277	func malformedSubscribePath(p string) bool {
278		rest, ok := strings.CutPrefix(p, "/v1/sessions/")
279		if !ok {
280			return false
281		}
282		segs := strings.Split(rest, "/")
283		for _, seg := range segs {
284			if seg == "subscribe" {
285				return !(len(segs) == 5 &&
286					segs[0] != "" &&
287					segs[1] == "documents" &&
288					segs[2] != "" &&
289					segs[3] == "changes")
290			}
291		}
292		return false
293	}
