295	// Handler exposes the HTTP surface over a private in-memory store. Use
296	// NewHandler with a durable store for real deployments.
297	func Handler() http.Handler {
298		s, err := store.Open("")
299		if err != nil {
300			log.Fatalf("open in-memory store: %v", err)
301		}
302		return NewHandler(s)
303	}
