351	func handleCreateSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
352		deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty
353	
354		var req sessionRequest
355		if !decodeJSONBody(w, r, &req) {
356			return
357		}
358		if req.SessionID == "" {
359			writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
360			return
361		}
362	
363		created, err := s.CreateSession(deviceID, req.SessionID)
364		if err != nil {
365			var conflict *store.ErrSessionConflict
366			switch {
367			case errors.Is(err, store.ErrDeviceNotFound):
368				writeError(w, http.StatusNotFound, "device not found")
369			case errors.As(err, &conflict):
370				writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
371			default:
372				writeError(w, http.StatusInternalServerError, "failed to create session")
373			}
374			return
375		}
376	
377		writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
378	}
