	const n = 16
	var wg sync.WaitGroup
	var winners, counterWins, gsetWins int
	var mu sync.Mutex
	for g := 0; g < n; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			typ := CRDTTypeCounter
			if g%2 == 0 {
				typ = CRDTTypeGSet
