func TestCRDTConcurrentCounterSubmits(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-a")
	registerDevice(t, h, "dev-b")

	const n = 40
	var wg sync.WaitGroup
	var failMu sync.Mutex
	var failures []string
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			dev := "dev-a"
			if i%2 == 0 {
				dev = "dev-b"
			}
			w, _ := crdtPost(t, h, "doc", map[string]any{
				"deviceId": dev,
				"type":     "counter",
				"ops":      []any{map[string]any{"id": "op-" + strconv.Itoa(i), "value": i + 1}},
			})
			if w.Code != http.StatusOK {
				failMu.Lock()
				failures = append(failures, fmt.Sprintf("op %d: %d", i, w.Code))
				failMu.Unlock()
			}
		}(i)
	}
	wg.Wait()
	if len(failures) != 0 {
		t.Fatalf("failed submits: %v", failures[:3])
	}

	// Every op commits completely; the merge is the sum of the two devices'
	// maxima: dev-b pushed 1,3,...,39 (max 39), dev-a pushed 2,4,...,40 (max 40).
	w, body := crdtState(t, h, "doc")
	if w.Code != http.StatusOK || body["value"].(float64) != 79 {
		t.Fatalf("state = %d %s, want counter 79", w.Code, w.Body.String())
	}
}

