131			"deviceId": "dev-a", "type": "counter",
132			"ops": []any{map[string]any{"id": "o1", "value": 5}},
133		})
134	
135		// Once fixed as a counter, a gset declaration is a 409 with no write.
136		w, _ := crdtPost(t, h, "doc", map[string]any{
137			"deviceId": "dev-a", "type": "gset",
138			"ops": []any{map[string]any{"id": "g1", "value": "x"}},
139		})
140		if w.Code != http.StatusConflict {
141			t.Fatalf("type conflict = %d, want 409", w.Code)
142		}
143	
144		// Backward cumulative contribution is a 409 with no write.
145		w, _ = crdtPost(t, h, "doc", map[string]any{
146			"deviceId": "dev-a", "type": "counter",
147			"ops": []any{map[string]any{"id": "o2", "value": 4}},
148		})
149		if w.Code != http.StatusConflict {
150			t.Fatalf("monotonic regression = %d, want 409", w.Code)
151		}
152	
153		// Same stable id with a different value is a 409 naming the conflict id.
154		w, body := crdtPost(t, h, "doc", map[string]any{
155			"deviceId": "dev-a", "type": "counter",
156			"ops": []any{map[string]any{"id": "o1", "value": 6}},
157		})
158		if w.Code != http.StatusConflict || body["conflictId"] != "o1" {
159			t.Fatalf("value conflict = %d body=%s", w.Code, w.Body.String())
160		}
161	
162		// Same stable id from a different device is likewise a 409.
163		w, _ = crdtPost(t, h, "doc", map[string]any{
164			"deviceId": "dev-b", "type": "counter",
165			"ops": []any{map[string]any{"id": "o1", "value": 5}},
166		})
167		if w.Code != http.StatusConflict {
168			t.Fatalf("device conflict = %d, want 409", w.Code)
169		}
170	
171		// A batch whose second op conflicts writes neither op.
172		w, _ = crdtPost(t, h, "doc", map[string]any{
173			"deviceId": "dev-b", "type": "counter",
174			"ops": []any{
175				map[string]any{"id": "fresh-1", "value": 5},
176				map[string]any{"id": "o1", "value": 5},
177			},
178		})
179		if w.Code != http.StatusConflict {
180			t.Fatalf("batch conflict = %d, want 409", w.Code)
181		}
182		w, body = crdtState(t, h, "doc")
183		if body["value"].(float64) != 5 {
